const dflt=(o,d)=>{for(const k in d){if(o[k]===undefined)o[k]=JSON.parse(JSON.stringify(d[k]));else if(d[k]&&typeof d[k]=='object'&&!Array.isArray(d[k]))dflt(o[k],d[k])}};
