$('#pform').onsubmit=async e=>{e.preventDefault();const old=ST.products.find(x=>x.id==eid)||{};const p={...old,id:eid||'',name:$('#a1').value,slug:$('#a0').value,cat:$('#a2').value,price:+$('#a3').value,sale:+$('#a4').value,stock:+$('#a5').value,color:$('#a6').value,desc:$('#a7').value,details:$('#d1').value,imgs:pimgs.filter(Boolean),blend:$('#a9').checked?1:0,best:$('#b1').checked?1:0,hide:$('#b2').checked?1:0,seo_title:$('#s1').value,seo_desc:$('#s2').value};
 const j=await api('save',{product:p});if(j.ok){setST(j.store);$('#pf').close();render();toast('Product saved and published')}else alert(j.err||'Could not save')};
