 if(t.dataset.i&&t.files[0]){sync();const j=await up(t.files[0],t.dataset.i=='hero.img'?1600:1000,t.dataset.i=='logo'?'image/png':'image/jpeg');if(j.path){sv(ST.site,t.dataset.i,j.path);await saveSite('Image saved')}else alert(j.err||'Upload failed')}
