const SECL={hero:'Hero (top banner)',marquee:'Scrolling banner',cats:'Category tiles',promo:'Promo banner',best:'Best sellers',shop:'All bags grid',why:'Why choose us',reviews:'Customer reviews',faq:'FAQ'};
const CT={text:'Text block',imgtext:'Image and text',banner:'Banner with button',products:'Product row',video:'YouTube video',html:'Custom HTML'};
const NAVI=[['cats','Categories'],['best','Best sellers'],['promo','Offers'],['shop','Shop'],['why','Why us'],['reviews','Reviews'],['faq','FAQ']],NAVD={cats:1,shop:1,why:1,faq:1};
function curOrder(){const def=['marquee','cats','promo','best','shop','why','reviews','faq'],all=[...def,...(ST.site.custom||[]).map(c=>'c_'+c.id)],o=(ST.site.order||[]).filter(k=>all.includes(k));all.forEach(k=>{if(!o.includes(k))o.push(k)});return [...new Set(o)]}
const udb=k=>`<button class="ib" data-so="${k}:-1" aria-label="Move up">Up</button><button class="ib" data-so="${k}:1" aria-label="Move down">Down</button>`;
function custForm(i,c){const p=`custom.${i}.`,t=c.type,cs=ST.site.cats||[];let h='';
 const common=F(p+'align','Text alignment','sel',[['left','Left'],['center','Centered']])+F(p+'bg','Background','sel',[['','None'],['soft','Soft white panel'],['brand','Brand color panel']]);
 if(t=='text')h=F(p+'title','Heading')+F(p+'sub','Subtitle (optional)')+F(p+'text','Text','area')+common;
 else if(t=='imgtext')h=F(p+'title','Heading')+F(p+'sub','Subtitle (optional)')+F(p+'text','Text','area')+F(p+'img','Photo','img')+F(p+'side','Photo position','sel',[['left','Left'],['right','Right']])+F(p+'cta','Button text (empty = no button)')+F(p+'link','Button link, for example #shop')+common;
 else if(t=='banner')h=F(p+'title','Headline')+F(p+'text','Text','area')+F(p+'img','Photo','img')+F(p+'cta','Button text (empty = no button)')+F(p+'link','Button link, for example #shop');
 else if(t=='products')h=F(p+'title','Heading')+F(p+'sub','Subtitle (optional)')+F(p+'cat','Which bags','sel',[['All','All bags'],['__best','Best sellers only'],...cs.map(x=>[x.n,x.n])])+F(p+'limit','How many bags (1 to 24)','number')+common;
 else if(t=='video')h=F(p+'title','Heading')+F(p+'sub','Subtitle (optional)')+F(p+'url','YouTube link')+F(p+'text','Caption (optional)')+common;
 else h=F(p+'title','Heading (optional)')+F(p+'sub','Subtitle (optional)')+F(p+'html','HTML code (only paste code you trust)','area')+common;
 return h}
function sects(){const o=curOrder(),cu=ST.site.custom||[];
 const row=k=>{if(k.startsWith('c_')){const i=cu.findIndex(c=>'c_'+c.id==k),c=cu[i];if(!c)return '';
  const enabled=+c.on!==0;
  return `<div class="rowx section-row"><div class="grow"><b>${esc(c.title||CT[c.type])}</b> <span class="chip2">${CT[c.type]||'Custom'}</span> <span class="chip2 ${enabled?'on':'off'}">${enabled?'On page':'Removed'}</span></div>${tg(`custom.${i}.on`,'On page')}<button class="ib ${enabled?'d':''}" data-section="c_${c.id}:${enabled?0:1}">${enabled?'Remove':'Add section'}</button>${udb(k)}<button class="ib" data-copysec="${i}">Duplicate</button><button class="ib d" data-delsec="${i}">Delete</button></div><details class="lr" ${openSec==c.id?'open':''}><summary><b>Edit this section</b></summary>${custForm(i,c)}</details>`}
  const value=gp(ST.site,'sections.'+k);
  const enabled=value!==0&&value!=='0'&&value!==false;
  return `<div class="rowx section-row"><div class="grow"><b>${SECL[k]}</b> <span class="chip2">Built-in</span> <span class="chip2 ${enabled?'on':'off'}">${enabled?'On page':'Removed'}</span></div>${tg('sections.'+k,'On page')}${udb(k)}<button class="ib ${enabled?'d':''}" data-section="${k}:${enabled?0:1}">${enabled?'Remove':'Add section'}</button></div>`};
 const heroValue=gp(ST.site,'sections.hero');
 const heroEnabled=heroValue!==0&&heroValue!=='0'&&heroValue!==false;
 const heroRow=`<div class="rowx section-row"><div class="grow"><b>${SECL.hero}</b> <span class="chip2">Always first</span> <span class="chip2 ${heroEnabled?'on':'off'}">${heroEnabled?'On page':'Removed'}</span></div>${tg('sections.hero','On page')}<button class="ib ${heroEnabled?'d':''}" data-section="hero:${heroEnabled?0:1}">${heroEnabled?'Remove':'Add section'}</button></div>`;
 return `<h2>Sections and layout</h2><div class="box"><h3>Sections on your home page</h3><p>Use <b>Remove</b> to hide a section without losing its content. Add it again whenever you want. Use Up and Down to change section order. Your custom sections can also be duplicated or permanently deleted.</p>${heroRow}${o.map(row).join('')}</div>
 <div class="box"><h3>Add a new section</h3><p>Pick a type. It is added at the bottom of the home page. You can then move it, edit it, switch it off or delete it.</p>${Object.entries(CT).map(([k,v])=>`<button class="ib" data-addsec="${k}">+ ${v}</button>`).join('')}</div>
 <div class="box"><h3>Section titles and style</h3><p>Leave a title empty to hide it.</p>${['cats','best','shop','why','reviews','faq'].map(k=>`<details class="lr"><summary><b>${SECL[k]}</b></summary>${F('titles.'+k,'Title')}${F('subs.'+k,'Subtitle (optional)')}${F('bgs.'+k,'Background','sel',[['','None'],['soft','Soft white panel'],['brand','Brand color panel']])}</details>`).join('')}</div>${SV}`}
function cats(){const cs=ST.site.cats||[],cn=c=>c._o||c.n,products=c=>ST.products.filter(p=>p.cat==cn(c)),cnt=c=>products(c).length,live=c=>+c.on?products(c).filter(p=>!p.hide).length:0;
 return `<h2>Categories</h2><p>Add, rename, enable, disable or remove categories. Disabling hides its products from shoppers without deleting them. Renaming a category updates its products automatically.</p>
 <div class="box"><h3>Add a category</h3><div class="tools"><input id="ncn" placeholder="New category name, for example Wallets" aria-label="New category name"><button class="btn" data-addcat>Add category</button></div></div>
 <div class="box"><h3>Your categories (${cs.length})</h3><label for="catsearch" class="sr">Search categories</label><input id="catsearch" type="search" placeholder="Search categories by name"><div class="tools"><button class="ib" data-catall="1">Enable all</button><button class="ib" data-catall="0">Disable all</button></div>
 <div class="tools"><label class="sw2"><input type="checkbox" data-catselectall style="width:auto;min-height:0"> Select visible</label><button class="ib" data-catbulk="on:1">Enable selected</button><button class="ib" data-catbulk="on:0">Disable selected</button><button class="ib" data-catbulk="tile:1">Show selected tiles</button><button class="ib" data-catbulk="tile:0">Hide selected tiles</button><button class="ib" data-catbulk="filter:1">Show selected filters</button><button class="ib" data-catbulk="filter:0">Hide selected filters</button></div>`+
 (cs.map((c,i)=>`<div class="cat-item" data-cat-search="${esc(c.n.toLocaleLowerCase())}"><div class="rowx"><label class="sw2"><input type="checkbox" data-catselect="${i}" aria-label="Select ${esc(c.n)}" style="width:auto;min-height:0"></label><div class="grow"><label for="cn${i}" class="sr">Category name</label><input id="cn${i}" data-p="cats.${i}.n" value="${esc(c.n)}"><small>${cnt(c)} product${cnt(c)==1?'':'s'}: ${live(c)} live, ${cnt(c)-live(c)} hidden</small></div>${tg(`cats.${i}.on`,'Enabled')}${tg(`cats.${i}.tile`,'Home tile')}${tg(`cats.${i}.filter`,'Shop filter')}<span class="chip2 ${+c.on?'on':'off'}">${+c.on?'Enabled':'Disabled'}</span><button class="ib ${+c.on?'d':''}" data-catenable="${i}:${+c.on?0:1}">${+c.on?'Disable':'Enable'}</button><button class="ib" data-cu="${i}:-1" aria-label="Move up">Up</button><button class="ib" data-cu="${i}:1" aria-label="Move down">Down</button><button class="ib d" data-cdel="${i}">Remove</button></div><details style="margin:0 0 6px"><summary>Tile photo</summary>${F(`cats.${i}.img`,'Photo for the home tile','img')}</details></div>`).join('')||'<p>No categories yet. Add your first one above.</p>')+`</div>${SV}`}
function openCdel(i){sync();const c=ST.site.cats[i],nm=c._o||c.n,ps=ST.products.filter(p=>p.cat==nm),oth=ST.site.cats.filter((_,j)=>j!=i);cdi=i;
 if(!ps.length){if(confirm('Delete the category "'+c.n+'"?'))delCat(i);return}
 const visible=+c.on?ps.filter(p=>!p.hide).length:0,hidden=ps.length-visible;
 $('#cdt').textContent='Delete "'+c.n+'"';$('#cdp').textContent=`${ps.length} product${ps.length===1?'':'s'} will be affected: ${visible} currently visible in the store and ${hidden} not currently visible. Choose what happens next.`;
 $('#cdo').innerHTML=(oth.length?`<label class="sw2"><input type="radio" name="cdm" value="move" checked> Move products to <select id="cdt2" style="width:auto;display:inline-block">${oth.map(x=>`<option>${esc(x.n)}</option>`).join('')}</select></label><br>`:'')+`<label class="sw2"><input type="radio" name="cdm" value="hide" ${oth.length?'':'checked'}> Hide products (keep them in the admin)</label><br><label class="sw2"><input type="radio" name="cdm" value="delete"> Permanently delete products</label>`;
 $('#cdl').showModal()}
async function delCat(i,mode,val){const c=ST.site.cats[i],nm=c._o||c.n,ids=ST.products.filter(p=>p.cat==nm).map(p=>p.id);ST.site.cats.splice(i,1);if(!catCheck())return;
 const b=siteBody();if(mode&&ids.length)b.bulk={ids,op:mode,val};const j=await api('save',b);if(j.ok){setST(j.store);render();toast('Category deleted')}else alert(j.err||'Could not delete')}
$('#cdgo').onclick=async()=>{const m=document.querySelector('input[name=cdm]:checked'),mode=m?m.value:'hide',val=mode=='move'?$('#cdt2').value:undefined;$('#cdl').close();await delCat(cdi,mode=='move'?'cat':mode,val)};
function hprev(){const s=ST.site,m=s.logoMode||'both',h=Math.max(20,Math.min(90,+(s.brand&&s.brand.h)||44)),ns=Math.max(14,Math.min(48,+(s.brand&&s.brand.ns)||26)),tag=s.brand&&s.brand.tag;
 const mark=`<span class="lm" style="--lh:${h}px" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M5 8h14l-1 12H6L5 8z"/><path d="M9 8a3 3 0 016 0"/></svg></span>`,
 nm=`<span class="lw"><span class="ln" style="font-size:${ns}px">${esc(s.name)}</span>${tag?`<small class="lt">${esc(tag)}</small>`:''}</span>`;let l;
 if(s.logo&&m!='name'){const im=`<img src="${esc(U(s.logo))}" alt="" style="height:${h}px;width:auto;border-radius:10px">`;l=m=='logo'?im:im+nm}else if(m=='name')l=nm;else l=(s.brand&&+s.brand.mark===0?'':mark)+nm;
 const links=NAVI.filter(([k])=>{const v=gp(s,'nav.'+k+'.on');return v===undefined||v===''?NAVD[k]:+v}).map(([k,t])=>esc(gp(s,'nav.'+k+'.l')||t));
 return `<div class="hprev"><span class="logo">${l}</span><nav>${links.map(x=>`<span>${x}</span>`).join('')}</nav></div>`}
function brand(){const s=ST.site,cu=s.custom||[],nrow=(k,lab,def,fb)=>`<div class="rowx">${tg('nav.'+k+'.on',lab,def)}<div class="grow"><label class="sr" for="nl_${k}">Menu label for ${esc(lab)}</label><input id="nl_${k}" data-p="nav.${k}.l" value="${esc(gp(s,'nav.'+k+'.l')||'')}" placeholder="${esc(fb)}"></div></div>`;
 return `<h2>Logo, header and menu</h2><div class="box"><h3>Header preview</h3>${hprev()}<p><small>The header shows your logo and store name together by default. Upload your logo below, or the built-in bag mark is used. Changes appear on the live store after you publish.</small></p></div>
 <div class="box"><h3>Logo and store name</h3>${F('name','Store name')} ${F('brand.tag','Tagline under the name (optional)')}${F('logo','Upload your logo (transparent PNG recommended)','img')}${F('logoMode','Header shows','sel',[['both','Logo and store name'],['logo','Logo only'],['name','Store name only']])}${F('brand.mark','Show the built-in bag icon next to the name when no logo is uploaded','chk')}<div class="f2"><div>${F('brand.h','Logo height in the header (20 to 90 px)','number')}</div><div>${F('brand.ns','Store name size (14 to 48 px)','number')}</div></div></div>
 <div class="box"><h3>Header</h3>${F('ui.sticky','Keep the header on screen while scrolling','chk')}${F('ui.ann','Show the announcement bar','chk')}${F('ann','Announcement text')}</div>
 <div class="box"><h3>Menu links</h3><p>Choose which links appear in the header menu and rename them. A link only shows when its section is on and has content.</p>${NAVI.map(([k,l])=>nrow(k,l,NAVD[k]?1:0,l)).join('')}${cu.map(c=>nrow('c_'+c.id,c.title||CT[c.type],0,c.title||CT[c.type])).join('')}</div>${SV}`}
function shopc(){return `<h2>Shop and product page</h2><div class="box"><h3>Bag grid</h3>${F('shop.cols','Bags per row on large screens (2 to 6)','number')}${F('shop.chips','Show the category buttons above the grid','chk')}${F('shop.search','Show the search box','chk')}${F('shop.sort','Show the sort menu','chk')}</div>
 <div class="box"><h3>Bag cards</h3>${F('ui.cardcat','Show the category name on cards','chk')}${F('ui.cardadd','Show the Add button on cards','chk')}${F('ui.badges','Show Sale and Best seller badges','chk')}${F('ui.wish','Show the heart (save to favourites) button','chk')}</div>
 <div class="box"><h3>Product page</h3>${F('ui.pwa','Show the Order on WhatsApp button','chk')}${F('ui.ptrust','Show the delivery and trust points','chk')}${F('ui.rel','Show related bags','chk')}${F('ui.share','Show share links','chk')}</div>${SV}`}
function look(){return `<h2>Look and effects</h2><div class="box"><h3>Colors</h3>${F('theme.a','Main color','color')}${F('theme.b','Second color','color')}</div><div class="box"><h3>Show or hide</h3>${F('ui.wa','Floating WhatsApp button','chk')}${F('ui.pre','Opening animation on the home page','chk')}${F('ui.spk','Cursor sparkles','chk')}${F('ui.blobs','Soft floating color blobs in the background','chk')}${F('ui.tilt','3D tilt when you hover over cards','chk')}${F('ui.prog','Page scroll progress bar','chk')}</div><div class="box"><h3>Footer</h3>${F('ui.fabout','Show the About text','chk')}${F('ui.fshop','Show the Shop links column','chk')}${F('ui.fcontact','Show the Contact column','chk')}</div><div class="box"><h3>Maintenance mode</h3>${F('maint.on','Close the store to visitors (you still see it while logged in here)','chk')}${F('maint.msg','Message to visitors','area')}</div><div class="box"><h3>Custom code</h3><p>Paste tracking or chat snippets, for example a TikTok Pixel. Only paste code you trust.</p>${F('code.head','Code for the head','area')}${F('code.body','Code for the end of the page','area')}</div>${SV}`}

function parseCSV(t){const rows=[];let r=[],c='',q=false;for(let i=0;i<t.length;i++){const ch=t[i];if(q){if(ch=='"'&&t[i+1]=='"'){c+='"';i++}else if(ch=='"')q=false;else c+=ch}else if(ch=='"')q=true;else if(ch==',')r.push(c),c='';else if(ch=='\n'||ch=='\r'){if(ch=='\r'&&t[i+1]=='\n')i++;r.push(c);c='';if(r.some(x=>x.trim()))rows.push(r);r=[]}else c+=ch}r.push(c);if(r.some(x=>x.trim()))rows.push(r);return rows}
function slip(o){const w=window.open('','_blank');if(!w)return;w.document.write(`<title>${esc(o.id)}</title><body style="font:16px sans-serif;max-width:560px;margin:20px auto"><h2>${esc(ST.site.name)}</h2><p><b>Order ${esc(o.id)}</b><br>${new Date(o.date).toLocaleString()}</p><p><b>${esc(o.name)}</b><br>${esc(o.phone)}<br>${esc(o.addr)}</p><table style="width:100%;border-collapse:collapse">${o.items.map(i=>`<tr><td>${i.n} x ${esc(i.name)}</td><td align="right">${money(i.n*i.price)}</td></tr>`).join('')}</table><p>Delivery: ${o.ship?money(o.ship):'Free'}<br><b>Total (cash on delivery): ${money(o.total)}</b></p>`);w.document.close();w.print()}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key=='s'){const b=$('[data-save]');if(b){e.preventDefault();b.click()}}});
